predicted_sql:
SELECT (SUM(CASE WHEN Birthday > '1930-12-31' THEN 1 ELSE 0 END) * 100.0) / COUNT(*) AS percentage
FROM Patient
WHERE SEX = 'F' AND Birthday IS NOT NULL;

SELECT 100.0 * SUM(CASE WHEN SEX = 'F' THEN 1 ELSE 0 END) / SUM(CASE WHEN SEX IN ('F','M') THEN 1 ELSE 0 END) AS percentage
FROM Patient
WHERE STRFTIME('%Y', Birthday) = '1980' AND Diagnosis = 'RA';

SELECT L.name
FROM Match M
JOIN League L ON M.league_id = L.id
WHERE M.season = '2008/2009'
GROUP BY L.name
HAVING COUNT(M.id) = (
  SELECT MAX(cnt) FROM (
    SELECT COUNT(id) AS cnt FROM Match WHERE season = '2008/2009' GROUP BY league_id
  ) AS sub
);

SELECT
(SELECT pa.jumping
 FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id
 WHERE p.id = 6 AND pa.date = (SELECT MAX(date) FROM Player_Attributes pa2 WHERE pa2.player_api_id = p.player_api_id)
) -
(SELECT pa.jumping
 FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id
 WHERE p.id = 23 AND pa.date = (SELECT MAX(date) FROM Player_Attributes pa2 WHERE pa2.player_api_id = p.player_api_id)
) AS difference;

SELECT ABS(
  (SELECT COUNT(superhero.id) FROM superhero JOIN publisher ON superhero.publisher_id = publisher.id WHERE publisher.publisher_name = 'DC Comics')
  -
  (SELECT COUNT(superhero.id) FROM superhero JOIN publisher ON superhero.publisher_id = publisher.id WHERE publisher.publisher_name = 'Marvel Comics')
) AS difference;

SELECT e.weight_kg - c.weight_kg AS difference
FROM superhero AS e, superhero AS c
WHERE e.full_name = 'Emil Blonsky' AND c.full_name = 'Charles Chandler';

SELECT (SUM(CASE WHEN colour.colour = 'Blue' THEN 1 ELSE 0 END) * 100.0) / COUNT(*) AS percentage
FROM superhero
LEFT JOIN colour ON superhero.eye_colour_id = colour.id;

SELECT 100.0 * (
  SELECT COUNT(*) FROM posts JOIN users ON posts.OwnerUserId = users.Id
  WHERE posts.Score > 5 AND users.Age > 65
) / (
  SELECT COUNT(*) FROM posts WHERE posts.Score > 5
) AS percentage;

SELECT CASE WHEN total = 0 THEN 0 ELSE (zero_upvotes * 100.0) / total END AS percentage
FROM (
  SELECT
    (SELECT COUNT(DISTINCT c.UserId) FROM comments c WHERE c.Score BETWEEN 5 AND 10 AND c.UserId IS NOT NULL) AS total,
    (SELECT COUNT(DISTINCT c.UserId) FROM comments c JOIN users u ON c.UserId = u.Id WHERE c.Score BETWEEN 5 AND 10 AND c.UserId IS NOT NULL AND u.UpVotes = 0) AS zero_upvotes
);

SELECT 100.0 * (
  (SELECT COUNT(DISTINCT cards.uuid) FROM cards JOIN foreign_data ON cards.uuid = foreign_data.uuid WHERE foreign_data.language = 'Chinese Simplified')
  /
  (SELECT COUNT(DISTINCT uuid) FROM cards)
) AS percentage;

SELECT bond_type
FROM bond
GROUP BY bond_type
HAVING COUNT(*) = (
  SELECT MAX(cnt) FROM (
    SELECT COUNT(*) AS cnt
    FROM bond
    GROUP BY bond_type
  )
);

SELECT 100.0 * SUM(CASE WHEN element = 'c' THEN 1 ELSE 0 END) / COUNT(*) AS percentage
FROM atom
WHERE molecule_id IN (SELECT DISTINCT molecule_id FROM bond WHERE bond_type = '=');

SELECT CASE WHEN denom=0 THEN NULL ELSE 100.0 * num / denom END
FROM (
  SELECT
    (SELECT COUNT(DISTINCT m.molecule_id) FROM molecule m JOIN bond b ON m.molecule_id = b.molecule_id WHERE b.bond_type = '#' AND m.label = '+') AS num,
    (SELECT COUNT(DISTINCT molecule_id) FROM bond WHERE bond_type = '#') AS denom
);

SELECT DISTINCT element FROM atom WHERE atom_id IN (
  SELECT atom_id FROM connected WHERE bond_id = 'TR001_10_11'
  UNION
  SELECT atom_id2 FROM connected WHERE bond_id = 'TR001_10_11'
);

SELECT CASE WHEN den.cnt=0 THEN NULL ELSE num.cnt*1.0/den.cnt END AS ratio
FROM (SELECT COUNT(*) AS cnt FROM schools WHERE County='Orange' AND StatusType='Merged' AND DOC='54') num,
     (SELECT COUNT(*) AS cnt FROM schools WHERE County='Orange' AND StatusType='Merged' AND DOC='52') den;
